    elif screen_id in {'dungeon_floor_preview', 'dungeon_boss_preview'}:
        controls.append(progress_control('dungeon_progress', 'Dungeon', '{dungeon_event}', '{dungeon_max}', 'dungeon'))
    elif screen_id == 'level_up':
