import json
from pathlib import Path
expected = {'status': 0.15, 'scene': 0.50, 'context': 0.20, 'actions': 0.15}
errors = []
for path in sorted(Path('uigames/hero_adventure/ui').glob('*.json')):
    data = json.loads(path.read_text())
    frames = {frame['id']: frame for frame in data.get('frames', [])}
    if set(frames) != set(expected):
        errors.append(f'{path}: frame ids {sorted(frames)}')
    for frame_id, ratio in expected.items():
        if abs(frames.get(frame_id, {}).get('ratio', -1) - ratio) > 1e-9:
            errors.append(f'{path}: {frame_id} ratio')
    for control in data.get('controls', []):
        if control.get('frame') not in expected:
            errors.append(f"{path}: invalid control frame {control.get('frame')}")
    if any(key in data for key in ('text', 'lists', 'buttons')):
        errors.append(f'{path}: legacy keys remain')
if errors:
    raise SystemExit('\n'.join(errors))
print(f'Validated {len(list(Path("uigames/hero_adventure/ui").glob("*.json")))} four-frame screens')
